excels.excel:

EXPORT WITH SHEET="成品出厂检验缺陷统计表", HEADER=true,
    MAPPING={"a":"产品型号","b":"检验批次","c":"抽检数量","d":"缺陷数量","e":"缺陷率","f":"判定结论","g":"检验员"},
    FORMAT={"c":"#,##0","d":"#,##0","e":"0.00%"},
    FORMULAS={
        E2:'D2/C2',E3:'D3/C3',E4:'D4/C4',E5:'D5/C5',E6:'D6/C6',E7:'D7/C7',
        C8:'SUM(C2:C7)',D8:'SUM(D2:D7)',E8:'D8/C8'
    },
    STYLE={
        ROW 8:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        E4:{color:red,bold:true}
    }
